@keyframes WACFadeIn {
    0% {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

@keyframes WACFadeInUp {
    0% {
        opacity: 0;
        transform: translateY(32px);
    }

    50% {
        transform: translateY(0);
    }

    to {
        opacity: 1;
    }
}

@keyframes WACFadeOut {
    0% {
        opacity: 1;
    }

    to {
        opacity: 0;
    }
}

@keyframes WACSlideInFromRight {
    0% {
        left: 100%;
    }

    to {
        left: 0;
    }
}

@keyframes WACSlideOutToRight {
    0% {
        left: 0;
    }

    to {
        left: 100%;
    }
}

