    0% {
        top: 0;
    }

    to {
        top: -100%;
    }
}

@keyframes WACSlideInFromLeft {
    0% {
        right: 100%;
    }

    to {
        right: 0;
    }
}

@keyframes WACSlideOutToLeft {
    0% {
        right: 0;
    }

    to {
        right: 100%;
    }
}

@keyframes WACSlideInFromBottom {
    0% {
        top: 100%;
    }

    to {
        top: 0;
    }
}

@keyframes WACSlideOutToBottom {
    0% {
        top: 0;
    }

    to {
        top: 100%;
    }
}

@keyframes WACLauncherIn {
    0% {
        bottom: calc(var(--cds-chat-LAUNCHER-position-bottom) - 16px);
        opacity: 0;
    }

    to {
        bottom: var(--cds-chat-LAUNCHER-position-bottom);
